create or replace function private.aios_validate_invocation_registry() returns trigger language plpgsql security definer set search_path = '' as $$ declare t public.aios_tools; v_hash text; begin if tg_op='UPDATE' then if new.organization_id is distinct from old.organization_id or new.agent_id is distinct from old.agent_id or new.task_id is distinct from old.task_id or new.tool_key is distinct from old.tool_key or new.tool_name is distinct from old.tool_name or new.authorization_version is distinct from old.authorization_version or new.approval_id is distinct from old.approval_id or new.arguments is distinct from old.arguments then if old.status not in ('requested','evaluating') then raise exception 'invocation authorization context is immutable after evaluation begins' using errcode='40001'; end if; end if; end if; select * into t from public.aios_tools where tool_key=coalesce(new.tool_key,new.tool_name); if t.id is null then raise exception 'tool is not registered' using errcode='22023'; end if; if not t.is_enabled or t.status<>'active' then raise exception 'tool is disabled or inactive' using errcode='42501'; end if; if new.tool_key is distinct from t.tool_key or new.tool_name is distinct from t.tool_key then raise exception 'tool identity does not match canonical registry' using errcode='22023'; end if; if not extensions.jsonb_matches_schema(t.input_schema::json,new.arguments) then raise exception 'tool arguments do not match registry input schema' using errcode='22023'; end if; v_hash=encode(extensions.digest(convert_to(new.arguments::text,'UTF8'),'sha256'),'hex'); if tg_op='INSERT' or (new.arguments is distinct from old.arguments and old.status in ('requested','evaluating')) then new.arguments_hash=v_hash; end if; return new; end $$;
